```python
import sys

# 并查集数据结构
class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size + 1))  # parent[i]表示节点i的父节点
        self.rank = [0] * (size + 1)          # rank[i]表示节点i的秩（树的高度）
        self.count = size                     # 初始连通块数为n

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])  # 路径压缩
        return self.parent[x]

    def union(self, x, y):
        x_root = self.find(x)
        y_root = self.find(y)
        if x_root == y_root:
            return False  # x和y已经在同一个连通块，不需要合并
        if self.rank[x_root] < self.rank[y_root]:
            self.parent[x_root] = y_root
        else:
            self.parent[y_root] = x_root
            if self.rank[x_root] == self.rank[y_root]:
                self.rank[x_root] += 1
        self.count -= 1  # 合并后连通块数减1
        return True

def main():
    # 读入数据
    input = sys.stdin.read().split()
    ptr = 0
    n = int(input[ptr])  # 节点数
    ptr += 1
    m = int(input[ptr])  # 边数
    ptr += 1

    uf = UnionFind(n)  # 初始化并查集
    sum_red = 0  # 红色边的权值和
    red_edges = []  # 存储红色边

    # 读入每一条边
    for _ in range(m):
        u = int(input[ptr])
        ptr += 1
        v = int(input[ptr])
        ptr += 1
        w = int(input[ptr])
        ptr += 1
        c = int(input[ptr])
        ptr += 1
        if c == 0:
            uf.union(u, v)  # 如果不是红色边，直接合并
        else:
            red_edges.append((u, v, w))  # 如果是红色边，存储
            sum_red += w

    # 初始连通块数
    C0 = uf.count

    # 对红色边按权值从小到大排序
    red_edges.sort(key=lambda x: x[2])

    # 存储在连通块数不超过k时，最大可以得到的权值
    min_retained = [0]
    sum_retained = 0
    for u, v, w in red_edges:
        root_u = uf.find(u)
        root_v = uf.find(v)
        if root_u != root_v:  # 如果u和v不在同一个连通块
            uf.union(root_u, root_v)  # 合并它们
            sum_retained += w  # 增加红色边的权值
            min_retained.append(sum_retained)
            if len(min_retained) - 1 == C0 - 1:
                break  # 合并到连通块数只剩下一个时停止

    # 输出结果
    for k in range(1, n + 1):
        if k >= C0:
            print(sum_red, end=" ")
        else:
            t_needed = C0 - k
            print(sum_red - min_retained[t_needed], end=" ")

if __name__ == "__main__":
    main()
```


