import java.util.*;

public class Main {
    static class UnionFind {
        int[] parent, rank;
        int count;

        public UnionFind(int size) {
            parent = new int[size + 1];
            rank = new int[size + 1];
            for (int i = 1; i <= size; i++) {
                parent[i] = i;
            }
            count = size;
        }

        public int find(int x) {
            if (parent[x] != x) {
                parent[x] = find(parent[x]);
            }
            return parent[x];
        }

        public boolean union(int x, int y) {
            int rootX = find(x);
            int rootY = find(y);
            if (rootX == rootY) {
                return false;
            }
            if (rank[rootX] < rank[rootY]) {
                parent[rootX] = rootY;
            } else {
                parent[rootY] = rootX;
                if (rank[rootX] == rank[rootY]) {
                    rank[rootX]++;
                }
            }
            count--;
            return true;
        }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int m = sc.nextInt();

        UnionFind uf = new UnionFind(n);
        long sumRed = 0;
        List<int[]> redEdges = new ArrayList<>();

        for (int i = 0; i < m; i++) {
            int u = sc.nextInt();
            int v = sc.nextInt();
            int w = sc.nextInt();
            int c = sc.nextInt();
            if (c == 0) {
                uf.union(u, v);
            } else {
                redEdges.add(new int[] {u, v, w});
                sumRed += w;
            }
        }

        int C0 = uf.count;
        redEdges.sort(Comparator.comparingInt(a -> a[2]));

        List<Long> minRetained = new ArrayList<>();
        long sumRetained = 0;
        minRetained.add(0L);

        for (int[] edge : redEdges) {
            int u = edge[0];
            int v = edge[1];
            int w = edge[2];
            int rootU = uf.find(u);
            int rootV = uf.find(v);
            if (rootU != rootV) {
                uf.union(rootU, rootV);
                sumRetained += w;
                minRetained.add(sumRetained);
                if (minRetained.size() - 1 == C0 - 1) {
                    break;
                }
            }
        }

        for (int k = 1; k <= n; k++) {
            if (k >= C0) {
                System.out.print(sumRed + " ");
            } else {
                int tNeeded = C0 - k;
                System.out.print(sumRed - minRetained.get(tNeeded) + " ");
            }
        }
    }
}
