```python
import sys

class UnionFind:
    def __init__(self, size):
        self.parent = list(range(size + 1))
        self.rank = [0] * (size + 1)
        self.count = size  # 当前孤岛数量

    def find(self, x):
        if self.parent[x] != x:
            self.parent[x] = self.find(self.parent[x])
        return self.parent[x]

    def union(self, x, y):
        rx = self.find(x)
        ry = self.find(y)
        if rx == ry:
            return False
        if self.rank[rx] < self.rank[ry]:
            self.parent[rx] = ry
        else:
            self.parent[ry] = rx
            if self.rank[rx] == self.rank[ry]:
                self.rank[rx] += 1
        self.count -= 1
        return True

def main():
    data = sys.stdin.read().split()
    it = iter(data)
    n = int(next(it))
    m = int(next(it))

    uf = UnionFind(n)
    sum_removable = 0
    removable_edges = []

    for _ in range(m):
        u = int(next(it))
        v = int(next(it))
        w = int(next(it))
        c = int(next(it))
        if c == 0:          # 不可拆除光缆，必须保留
            uf.union(u, v)
        else:               # 可拆除光缆
            removable_edges.append((u, v, w))
            sum_removable += w

    C0 = uf.count           # 初始孤岛数量

    # 收益值从小到大排序
    removable_edges.sort(key=lambda x: x[2])

    min_retained = [0]      # min_retained[t] 表示保留 t 条后已保留的最小收益和
    sum_retained = 0

    for u, v, w in removable_edges:
        if uf.find(u) != uf.find(v):
            uf.union(u, v)
            sum_retained += w
            min_retained.append(sum_retained)
            if len(min_retained) - 1 == C0 - 1:  # 已经合并到只剩1个孤岛
                break

    # 输出答案
    ans = []
    for k in range(1, n + 1):
        if k >= C0:
            ans.append(str(sum_removable))
        else:
            need = C0 - k
            ans.append(str(sum_removable - min_retained[need]))
    print(' '.join(ans))

if __name__ == '__main__':
    main()
